<?php
require 'config/database.php';require 'includes/functions.php';$title='Products';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$s=$pdo->prepare("UPDATE products SET is_archived=1 WHERE id=?");$s->execute([$id]);flash('success','Product archived successfully.');header('Location: products.php');exit;}
$q=trim($_GET['q']??'');$sql="SELECT * FROM products WHERE is_archived=0";$args=[];if($q!==''){$sql.=" AND (name LIKE ? OR sku LIKE ? OR category LIKE ?)";$args=["%$q%","%$q%","%$q%"];} $sql.=" ORDER BY name";$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();require 'includes/header.php';?>
<section class="heading"><div><small>CATALOG</small><h1>Products</h1><p>Manage products, unit costs and stock levels.</p></div><a class="btn primary" href="product_form.php">＋ Add product</a></section><section class="panel"><div class="panel-head"><div><h2>All products <span class="pill bluepill"><?=count($rows)?></span></h2><p>Search and manage active inventory items.</p></div><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, SKU, category…"><button class="btn secondary">Search</button></form></div><?php if(!$rows):?><div class="empty"><b>No products found</b><p>Add a product or change your search.</p><a class="btn primary" href="product_form.php">Add product</a></div><?php else:?><div class="scroll"><table><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>UNIT COST</th><th>IN STOCK</th><th>REORDER LEVEL</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($rows as $p):$isLow=$p['quantity']<=$p['reorder_level'];?><tr><td><b><?=e($p['name'])?></b><small><?=e($p['sku'])?></small></td><td><?=e($p['category']?:'—')?></td><td><?=money($p['unit_cost'])?></td><td><b><?=$p['quantity']?></b></td><td><?=$p['reorder_level']?></td><td><span class="pill <?=$isLow?'warning':'good'?>"><?=$isLow?'Low stock':'In stock'?></span></td><td class="actions"><a href="product_form.php?id=<?=$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Archive this product?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button>Archive</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require 'includes/footer.php';?>